[
  {
    "statement": "Different seeding strategies in North American grasslands can have several negative impacts on existing native vegetation.",
    "citations": []
  },
  {
    "statement": "Sowing grass seeds specifically has been documented to reduce the abundance of native forb species.",
    "citations": []
  },
  {
    "statement": "Sowing grass seeds specifically has been documented to reduce the abundance of shrub species.",
